def parse_claude_reset_seconds(line: str, now: float | None = None) -> int | None:
    match = CLAUDE_LIMIT_PATTERN.search(line)
    if match is None:
        return None
    hour = int(match.group(1))
    minute = int(match.group(2) or 0)
    meridiem = (match.group(3) or "").lower()
    if meridiem == "pm" and hour < 12:
        hour += 12
    if meridiem == "am" and hour == 12:
        hour = 0
    try:
        zone = ZoneInfo(match.group(4).strip())
    except (ZoneInfoNotFoundError, ValueError):
        return DEFAULT_RATE_LIMIT_WAIT_SECONDS
    current = datetime.fromtimestamp(now if now is not None else time.time(), zone)
    reset = current.replace(hour=hour, minute=minute, second=0, microsecond=0)
    if reset <= current:
        reset += timedelta(days=1)
    return max(60, int((reset - current).total_seconds()))


def mark_agent_limited(agent: str, wait_seconds: int) -> None:
    agent_limited_until[agent] = time.time() + wait_seconds


def cli_agent() -> str | None:
    if claude_mode_enabled and time.time() >= agent_limited_until["claude"]:
        return "claude"
    if time.time() >= agent_limited_until["opencode"]:
        return "opencode"
    return None


def handle_rate_limit(goal: str) -> None:
    available = cli_agent()
    if available is not None:
        print(f"falling back to {available} (smartest agent not rate limited)", flush=True)
        return
    deadlines = [agent_limited_until["opencode"]]
    if claude_mode_enabled:
        deadlines.append(agent_limited_until["claude"])
    wait_seconds = max(0, int(min(deadlines) - time.time()))
    rate_limit_handoff(goal, wait_seconds)


